<?php if ($metrics) { require __DIR__ . '/../../components/live-summary.php'; } else { ?><div class="page-heading"><h1>Mis productos</h1><span class="muted">Publica y edita tus productos</span></div><?php } ?>
<div class="seller-layout"><section class="panel form-panel"><form method="post" enctype="multipart/form-data" action="/<?= e($page) ?>.php"><?= csrf_field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= e($edit['id'] ?? 0) ?>"><h2><?= $edit ? 'Editar producto' : 'Nuevo producto' ?></h2><label for="product-name">Nombre</label><input id="product-name" name="nombre" required maxlength="120" value="<?= e($edit['nombre'] ?? '') ?>"><label for="description">Descripción</label><textarea id="description" name="descripcion" required maxlength="2000" rows="3"><?= e($edit['descripcion'] ?? '') ?></textarea><div class="form-row"><div><label for="price">Precio (USD)</label><input id="price" name="precio" type="number" min="0.01" max="999999.99" step="0.01" required value="<?= e($edit['precio'] ?? '') ?>"></div><div><label for="stock">Existencias</label><input id="stock" name="stock" type="number" min="0" max="999999" step="1" required value="<?= e($edit['stock'] ?? '') ?>"></div></div>
<?php if ($role === 'administrador'): ?><label for="seller">Vendedor activo</label><select id="seller" name="vendedor_id" required><?php foreach ($sellers as $seller): ?><option value="<?= e($seller['id']) ?>" <?= (int)($edit['vendedor_id'] ?? 0) === (int)$seller['id'] ? 'selected' : '' ?>><?= e($seller['nombre']) ?></option><?php endforeach; ?></select><?php endif; ?>
<label for="active">Estado</label><select id="active" name="activo"><option value="1" <?= ($edit['activo'] ?? 1) ? 'selected' : '' ?>>Activo</option><option value="0" <?= isset($edit) && !$edit['activo'] ? 'selected' : '' ?>>Retirado del catálogo</option></select><div class="file-field"><label for="product-image">Imagen del producto</label><input id="product-image" name="imagen" type="file" accept="image/jpeg,image/png,image/webp" <?= !$edit ? 'required' : '' ?>><p class="form-help">JPG, PNG o WEBP, máx. 2 MB y 4096 px. En edición, dejar vacío conserva la imagen.</p><img id="image-preview" class="upload-preview" alt="Vista previa" <?= !$edit ? 'hidden' : 'src="' . e(image_url($edit['imagen'])) . '"' ?>></div><button class="wide"><?= $edit ? 'Guardar cambios' : 'Publicar producto' ?></button><a class="button secondary wide" href="/<?= e($page) ?>.php">Nuevo producto</a></form></section>
<section class="panel"><div class="panel-heading"><h2><?= $role === 'vendedor' ? 'Mis publicaciones' : 'Productos' ?></h2><span><?= count($products) ?> productos</span></div><div class="table-scroll"><table><caption class="sr-only">Productos gestionables</caption><thead><tr><th>Producto</th><th>Precio</th><th>Stock</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach ($products as $p): ?><tr><td><b><?= e($p['nombre']) ?></b></td><td><?= money(cents($p['precio'])) ?></td><td><?= e($p['stock']) ?></td><td><?= $p['activo'] ? 'Activo' : 'Retirado' ?></td><td><div class="table-actions"><a href="/<?= e($page) ?>.php?editar=<?= e($p['id']) ?>">Editar</a><?php if ($role === 'administrador'): ?><form method="post" action="/admin-productos.php" data-confirm="¿Eliminar este producto? Se conservarán sus detalles de facturas."><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($p['id']) ?>"><button class="text-button danger" name="action" value="delete">Eliminar</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div></section></div>
